#!/usr/bin/env bash
# Reports whether a substring occurs inside a main string.

set -u

script_name=$(basename "$0")

usage() {
    printf 'Usage: %s "main string" "substring"\n' "$script_name" >&2
}

# Print the 1-based index of the first occurrence of $2 in $1, or 0 if absent.
find_index() {
    local haystack=$1 needle=$2 prefix
    case $haystack in
        *"$needle"*)
            prefix=${haystack%%"$needle"*}
            echo $(( ${#prefix} + 1 ))
            ;;
        *)
            echo 0
            ;;
    esac
}

# Print how many non-overlapping times $2 occurs in $1.
count_occurrences() {
    local haystack=$1 needle=$2 total=0 index
    while [ -n "$haystack" ]; do
        index=$(find_index "$haystack" "$needle")
        [ "$index" -eq 0 ] && break
        total=$(( total + 1 ))
        haystack=${haystack:index + ${#needle} - 1}
    done
    echo "$total"
}

format_summary() {
    local position=$1 count=$2
    printf 'first match at character %d, %d occurrence(s)' "$position" "$count"
}

report() {
    local haystack=$1 needle=$2 position count summary
    position=$(find_index "$haystack" "$needle")
    if [ "$position" -eq 0 ]; then
        echo "Substring not found."
        return 1
    fi
    count=$(count_occurrences "$haystack" "$needle")
    summary=$(format_summary "$position" "$count")
    echo "Substring found."
    printf '%s\n' "$summary" >&2
}

main() {
    if [ "$#" -ne 2 ]; then
        usage
        return 2
    fi
    if [ -z "$2" ]; then
        echo "Error: the substring must not be empty." >&2
        return 2
    fi
    report "$1" "$2"
}

main "$@"

