#!/usr/bin/env bash
# Print the permissions of files/directories in symbolic and octal form.

set -uo pipefail

progname=$(basename -- "$0")

usage() {
    printf 'Usage: %s PATH [PATH...]\n' "$progname" >&2
}

# First 10 characters of the long listing, e.g. -rw-r--r-- or drwxr-xr-x
symbolic_perms() {
    local entry field
    entry=$(ls -ld -- "$1") || return 1
    field=${entry%% *}
    printf '%s\n' "${field:0:10}"
}

# Convert a symbolic mode string into its octal representation.
octal_from_symbolic() {
    local sym=$1
    [[ ${#sym} -eq 10 ]] || return 1
    local perms=${sym:1:9}
    local special=0 digits='' offset group value sbit
    for offset in 0 3 6; do
        group=${perms:offset:3}
        case $offset in
            0) sbit=4 ;;
            3) sbit=2 ;;
            6) sbit=1 ;;
        esac
        value=0
        [[ ${group:0:1} == r ]] && value=$((value + 4))
        [[ ${group:1:1} == w ]] && value=$((value + 2))
        case ${group:2:1} in
            x) value=$((value + 1)) ;;
            s|t) value=$((value + 1)); special=$((special + sbit)) ;;
            S|T) special=$((special + sbit)) ;;
        esac
        digits+=$value
    done
    if ((special)); then
        printf '%d%s\n' "$special" "$digits"
    else
        printf '%s\n' "$digits"
    fi
}

# Prefer stat (GNU, then BSD), fall back to parsing the symbolic mode.
octal_perms() {
    local path=$1 value sym
    value=$(stat -c '%a' -- "$path" 2>/dev/null) && { printf '%s\n' "$value"; return 0; }
    value=$(stat -f '%Lp' -- "$path" 2>/dev/null) && { printf '%s\n' "$value"; return 0; }
    sym=$(symbolic_perms "$path") || return 1
    octal_from_symbolic "$sym"
}

report() {
    local path=$1 sym oct
    sym=$(symbolic_perms "$path") || return 1
    oct=$(octal_perms "$path") || return 1
    printf 'Symbolic: %s\n' "$sym"
    printf 'Octal: %s\n' "$oct"
}

main() {
    local path status=0
    if (($# == 0)); then
        usage
        return 2
    fi
    for path in "$@"; do
        if [[ ! -e $path && ! -L $path ]]; then
            printf '%s: %s: No such file or directory\n' "$progname" "$path" >&2
            status=1
            continue
        fi
        (($# > 1)) && printf '%s:\n' "$path"
        report "$path" || status=1
    done
    return "$status"
}

main "$@"

