#!/usr/bin/env bash
# Extract the domain name from a URL given on the command line.

set -u

# Remove the scheme ("https://", "ftp://", "//") if present.
strip_scheme() {
    local url=$1
    url=${url#*://}
    printf '%s' "${url#//}"
}

# Keep only the authority: cut path, query and fragment.
authority_of() {
    local rest
    rest=$(strip_scheme "$1")
    rest=${rest%%\#*}
    rest=${rest%%\?*}
    printf '%s' "${rest%%/*}"
}

# Drop any "user:password@" part that precedes the host.
strip_userinfo() {
    local authority=$1
    printf '%s' "${authority##*@}"
}

# Remove a trailing ":port" but leave IPv6 literals alone.
strip_port() {
    local host=$1
    case $host in
        \[*\]*) printf '%s' "${host%%\]*}]" ;;
        *:*)    printf '%s' "${host%:*}" ;;
        *)      printf '%s' "$host" ;;
    esac
}

# Lowercase the host and remove a leading "www." label.
normalize_host() {
    local host
    host=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')
    host=${host%.}
    printf '%s' "${host#www.}"
}

domain_name() {
    local authority userinfoless host
    authority=$(authority_of "$1")
    userinfoless=$(strip_userinfo "$authority")
    host=$(strip_port "$userinfoless")
    if [[ -z $host ]]; then
        return 1
    fi
    normalize_host "$host"
}

main() {
    if (( $# != 1 )); then
        printf 'usage: %s URL\n' "${0##*/}" >&2
        return 2
    fi

    local domain
    if ! domain=$(domain_name "$1"); then
        printf 'error: no host found in %s\n' "$1" >&2
        return 1
    fi

    printf '%s\n' "$domain"
}

main "$@"

