#!/usr/bin/env bash
# Print the header (first) row of a CSV file.
set -u

die() {
    printf 'error: %s\n' "$*" >&2
    exit 1
}

usage() {
    printf 'usage: %s CSVFILE\n' "$(basename -- "$0")" >&2
    exit 2
}

validate_csv_path() {
    local path=$1
    [[ -e $path ]] || die "no such file: $path"
    [[ -f $path ]] || die "not a regular file: $path"
    [[ -r $path ]] || die "not readable: $path"
    local size
    size=$(wc -c < "$path")
    (( size > 0 )) || die "file is empty: $(basename -- "$path")"
}

strip_bom() {
    printf '%s' "$1" | sed $'1s/^\xef\xbb\xbf//'
}

read_header() {
    local path=$1 raw
    raw=$(head -n 1 -- "$path" | tr -d '\r')
    [[ -n $raw ]] || die "header row is blank: $(basename -- "$path")"
    strip_bom "$raw"
}

count_char() {
    local line=$1 ch=$2
    printf '%s' "$line" | tr -dc "$ch" | wc -c
}

detect_delimiter() {
    local line=$1 best=',' best_count=0 cand count
    for cand in ',' ';' '|' $'\t'; do
        count=$(count_char "$line" "$cand")
        if (( count > best_count )); then
            best=$cand
            best_count=$count
        fi
    done
    printf '%s' "$best"
}

count_fields() {
    local line=$1 delim=$2
    awk -v FS="$delim" '{print NF}' <<< "$line"
}

main() {
    (( $# == 1 )) || usage
    local file=$1 header delim fields
    validate_csv_path "$file"
    header=$(read_header "$file")
    printf '%s\n' "$header"

    delim=$(detect_delimiter "$header")
    fields=$(count_fields "$header" "$delim")
    printf '%s: %s column(s), delimiter %q\n' \
        "$(basename -- "$file")" "$fields" "$delim" >&2
}

