#!/usr/bin/env bash
#
# char_count.sh -- print the number of characters in a string.
#
# Usage: char_count.sh [--bytes | --report] [-f FILE | STRING]

set -uo pipefail

PROG=$(basename "$0")

usage() {
    printf 'Usage: %s [--bytes | --report] [-f FILE | STRING]\n' "$PROG" >&2
}

die() {
    printf '%s: %s\n' "$PROG" "$1" >&2
    exit 1
}

# Characters, as understood by the current locale.
char_count() {
    local text=$1
    printf '%s\n' "${#text}"
}

# Bytes used to store the text; wc pads its output on some systems, so the
# arithmetic expansion normalises the number before printing it.
byte_count() {
    local text=$1 n
    n=$(printf '%s' "$text" | wc -c)
    printf '%s\n' "$((n))"
}

word_count() {
    local text=$1 n
    n=$(printf '%s' "$text" | wc -w)
    printf '%s\n' "$((n))"
}

read_file() {
    local path=$1
    [ -r "$path" ] || die "cannot read file: $path"
    cat -- "$path"
}

report() {
    local text=$1 chars bytes words
    chars=$(char_count "$text")
    bytes=$(byte_count "$text")
    words=$(word_count "$text")
    printf 'characters: %s\n' "$chars"
    printf 'bytes:      %s\n' "$bytes"
    printf 'words:      %s\n' "$words"
}

main() {
    local mode=chars file= text= have_text=0

    while [ "$#" -gt 0 ]; do
        case $1 in
            --bytes)  mode=bytes ;;
            --report) mode=report ;;
            -f) [ "$#" -ge 2 ] || die "option -f needs a file name"
                file=$2
                shift ;;
            -h|--help) usage; return 0 ;;
            --) shift; break ;;
            -*) die "unknown option: $1" ;;
            *)  text=$1
                have_text=1 ;;
        esac
        shift
    done

    if [ -n "$file" ]; then
        text=$(read_file "$file")
    elif [ "$have_text" -eq 0 ]; then
        usage
        return 1
    fi

    case $mode in
        chars)  char_count "$text" ;;
        bytes)  byte_count "$text" ;;
        report) report "$text" ;;
    esac
}

main "$@"

