#!/usr/bin/env bash
#
# concat.sh -- join two strings and print the result.
#
set -euo pipefail

readonly SCRIPT_NAME=$(basename "$0")

usage() {
  cat <<EOF
Usage: $SCRIPT_NAME [-v] STRING1 STRING2
       $SCRIPT_NAME -h

Prints STRING1 and STRING2 concatenated, with no separator.

Options:
  -v, --verbose   also print a breakdown of the operands on stderr
  -h, --help      show this help text
EOF
}

die() {
  printf '%s: %s\n' "$SCRIPT_NAME" "$1" >&2
  usage >&2
  exit 1
}

concat() {
  printf '%s%s' "$1" "$2"
}

# Render a string so that spaces and control characters stay visible.
quote() {
  printf '%q' "$1"
}

max_len() {
  local widest=0 s
  for s in "$@"; do
    if (( ${#s} > widest )); then
      widest=${#s}
    fi
  done
  printf '%s' "$widest"
}

describe() {
  printf '%-8s %-*s (%d chars)\n' "$1" "$4" "$2" "$3" >&2
}

report() {
  local shown_first shown_second shown_joined width
  shown_first=$(quote "$1")
  shown_second=$(quote "$2")
  shown_joined=$(quote "$3")
  width=$(max_len "$shown_first" "$shown_second" "$shown_joined")
  describe 'first:' "$shown_first" "${#1}" "$width"
  describe 'second:' "$shown_second" "${#2}" "$width"
  describe 'result:' "$shown_joined" "${#3}" "$width"
}

main() {
  local verbose=0
  local -a operands=()

  while (( $# > 0 )); do
    case $1 in
      -v|--verbose) verbose=1; shift ;;
      -h|--help)    usage; return 0 ;;
      --)           shift; operands+=("$@"); break ;;
      -?*)          die "unknown option: $1" ;;
      *)            operands+=("$1"); shift ;;
    esac
  done

  (( ${#operands[@]} == 2 )) ||
    die "expected exactly two string arguments, got ${#operands[@]}"

  local joined
  joined=$(concat "${operands[0]}" "${operands[1]}")
  printf '%s\n' "$joined"

  if (( verbose )); then
    report "${operands[0]}" "${operands[1]}" "$joined"
  fi
}

main "$@"

