#!/usr/bin/env bash
# validate_int.sh - report whether a value is a decimal integer.
set -u

prog=`basename "$0"`
readonly VALID_MSG='Valid integer'
readonly INVALID_MSG='Invalid integer'

usage() {
    printf 'usage: %s <value>\n' "$prog" >&2
    printf '       %s -   (validate one value per line of stdin)\n' "$prog" >&2
}

# Leading '+' or '-', if the value carries one.
sign_of() {
    case "$1" in
        -*) printf '%s' '-' ;;
        +*) printf '%s' '+' ;;
    esac
}

digits_of() {
    local raw="$1" sign
    sign=`sign_of "$raw"`
    printf '%s' "${raw#"$sign"}"
}

# An integer is an optional sign followed by one or more decimal digits.
is_integer() {
    local body
    body=`digits_of "$1"`
    [ -n "$body" ] || return 1
    case "$body" in
        *[!0-9]*) return 1 ;;
    esac
}

verdict_text() {
    if is_integer "$1"; then
        printf '%s' "$VALID_MSG"
    else
        printf '%s' "$INVALID_MSG"
    fi
}

check_value() {
    local verdict
    verdict=`verdict_text "$1"`
    printf '%s\n' "$verdict"
    [ "$verdict" = "$VALID_MSG" ]
}

# Piped input often carries stray blanks or a trailing carriage return.
trim() {
    local s="$1"
    s="${s#"${s%%[![:space:]]*}"}"
    printf '%s' "${s%"${s##*[![:space:]]}"}"
}

validate_stream() {
    local line rc=0
    while IFS= read -r line; do
        check_value "`trim "$line"`" || rc=1
    done
    return "$rc"
}

main() {
    if [ "$#" -ne 1 ]; then
        usage
        return 2
    fi
    case $1 in
        -h|--help) usage; return 0 ;;
        -) validate_stream ;;
        *) check_value "$1" ;;
    esac
}

main "$@"

