#!/usr/bin/env bash
# Print every Nth line of a file.

usage() {
    echo "usage: $(basename "$0") FILE N" >&2
    exit 2
}

die() {
    echo "$(basename "$0"): $*" >&2
    exit 1
}

is_positive_int() {
    local value=$1
    [[ $value =~ ^[1-9][0-9]*$ ]]
}

validate_file() {
    local file=$1
    [[ -f $file ]] || die "no such file: $file"
    [[ -r $file ]] || die "cannot read file: $file"
}

count_lines() {
    local file=$1
    local total
    total=$(wc -l < "$file")
    echo "$total"
}

every_nth() {
    local file=$1 step=$2
    awk -v n="$step" 'NR % n == 0' "$file"
}

report() {
    local file=$1 step=$2
    local total selected
    total=$(count_lines "$file")
    selected=$(every_nth "$file" "$step" | wc -l)
    echo "$(basename "$file"): printed $selected of $total lines (step $step)" >&2
}

main() {
    [[ $# -eq 2 ]] || usage

    local file=$1 step=$2
    validate_file "$file"
    is_positive_int "$step" || die "N must be a positive integer, got: $step"

    local lines
    lines=$(every_nth "$file" "$step")
    [[ -n $lines ]] && printf '%s\n' "$lines"

    report "$file" "$step"
}

main "$@"

