#!/usr/bin/env bash
#
# remove_last_n.sh — print a string with its last N characters removed.
#
# Usage: remove_last_n.sh [-v] <string> <n>

set -u

readonly PROG="$(basename "$0")"

usage() {
    printf 'Usage: %s [-v] <string> <n>\n' "$PROG" >&2
}

die() {
    printf '%s: %s\n' "$PROG" "$1" >&2
    exit 1
}

main() {
    local verbose=0
    while [[ $# -gt 0 && "$1" == -?* ]]; do
        case "$1" in
            -v|--verbose) verbose=1 ;;
            -h|--help) usage; exit 0 ;;
            --) shift; break ;;
            *) die "unknown option: $1" ;;
        esac
        shift
    done

    if (( $# != 2 )); then
        usage
        exit 1
    fi

    local input="$1" rawcount="$2"
    is_integer "$rawcount" || die "not an integer: '$rawcount'"

    local count
    count="$(normalise_count "$rawcount")"
    (( count < 0 )) && die "count must be non-negative: $count"

    local dropped
    dropped="$(effective_count "$count" "${#input}")"

    if (( verbose )); then
        local removed
        removed="$(suffix_of "$input" "$dropped")"
        printf '%s: dropping %d character(s): %s\n' "$PROG" "$dropped" "$removed" >&2
    fi

    local result
    result="$(remove_last_n "$input" "$dropped")"
    printf '%s\n' "$result"
}

# Succeeds only for a string of decimal digits, optionally signed.
is_integer() {
    [[ "$1" =~ ^[+-]?[0-9]+$ ]]
}

# Normalise "+7" / "007" style input to a plain decimal number.
normalise_count() {
    printf '%d\n' "$(($1))"
}

# Clamp a removal count to the length of the string it applies to.
effective_count() {
    local n="$1" length="$2"
    (( n > length )) && n="$length"
    printf '%d\n' "$n"
}

# The leading characters of str that survive dropping the last n.
remove_last_n() {
    local str="$1" n="$2"
    printf '%s\n' "${str:0:${#str}-n}"
}

# The trailing n characters of str.
suffix_of() {
    local str="$1" n="$2"
    printf '%s\n' "${str:${#str}-n}"
}

main "$@"

