#
# List all groups a given user belongs to, one per line.

set -u

PROGNAME=$(basename "$0")

usage() {
    printf 'Usage: %s USERNAME\n' "$PROGNAME" >&2
}

# Resolve an account (name or numeric UID) to its canonical login name.
canonical_user() {
    local entry
    entry=$(getent passwd "$1") || return 1
    printf '%s\n' "${entry%%:*}"
}

# Primary group name, resolved through the user's GID.
primary_group() {
    local user=$1
    local gid
    gid=$(id -g "$user")
    local entry
    entry=$(getent group "$gid")
    if [ -n "$entry" ]; then
        printf '%s\n' "${entry%%:*}"
    else
        printf '%s\n' "$gid"
    fi
}

# Every group whose member list mentions the user.
supplementary_groups() {
    local user=$1
    getent group | awk -F: -v user="$user" '
        {
            n = split($4, members, ",")
            for (i = 1; i <= n; i++)
                if (members[i] == user)
                    print $1
        }'
}

# Primary group first, then the supplementary ones, duplicates removed.
user_groups() {
    local user=$1
    {
        primary_group "$user"
        supplementary_groups "$user"
    } | awk '!seen[$0]++'
}

main() {
    if [ "$#" -ne 1 ]; then
        usage
        return 2
    fi

    local user
    user=$(canonical_user "$1") || {
        printf '%s: no such user: %s\n' "$PROGNAME" "$1" >&2
        return 1
    }

    local groups
    groups=$(user_groups "$user")
    if [ -z "$groups" ]; then
        printf '%s: no groups found for %s\n' "$PROGNAME" "$user" >&2
        return 1
    fi

    printf '%s\n' "$groups"
}

main "$@"

